static dm_Dss *dm_Dss_from(int64_t n, const dan_str *ks, const dan_str *vs) {
    dm_Dss *d = dm_Dss_new();
    for (int64_t i = 0; i < n; i++) dm_Dss_put(d, ks[i], vs[i]);
    return d;
}
static dan_str dm_Dss_get(const dm_Dss *d, dan_str k, int line) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return d->vals[e];
}
static dan_str *dm_Dss_at(dm_Dss *d, dan_str k, int line) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return &d->vals[e];
}
static bool dm_Dss_contains(const dm_Dss *d, dan_str k) { return dm_Dss_lookup(d, k, dan_hash_s(k)) >= 0; }

static do_s dm_Dss_find(const dm_Dss *d, dan_str k) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    return e < 0 ? do_s_none() : do_s_some(d->vals[e]);
}
static dan_str dm_Dss_get_or(const dm_Dss *d, dan_str k, dan_str v) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    return e < 0 ? v : d->vals[e];
}
static void dm_Dss_remove(dm_Dss *d, dan_str k) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    if (e >= 0) { d->alive[e] = false; d->len--; dan_str_release(d->keys[e]); dan_str_release(d->vals[e]); }
}
static dl_Ls *dm_Dss_keys(const dm_Dss *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->keys[e]);
    return r;
}
static dl_Ls *dm_Dss_values(const dm_Dss *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->vals[e]);
    return r;
}
/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_Dss *dm_Dss_copy(const dm_Dss *d) {
    dm_Dss *r = dm_Dss_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_Dss_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dan_str_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_Dss_reindex(r);
    return r;
}
static dm_Dss *dm_Dss_mut(dm_Dss **pp) {
    dm_Dss *d = *pp;
    if (d->h.rc > 1) { dm_Dss *r = dm_Dss_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_Dss_str(const dm_Dss *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dan_quote_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_Dss_write(const dm_Dss *d) { fputs(dm_Dss_str(d), stdout); }


static bool dm_Dss_eq(const dm_Dss *x, const dm_Dss *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_Dss_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dan_str a = x->vals[e]; dan_str b = y->vals[f];
        if (!(dan_str_eq(a, b))) return false;
    }
    return true;
}


/* ---- dictionary {стр: модули.Модуль} ---- */
struct dm_DsTmoduliu2eModulq { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dt_moduliu2eModulq *vals; uint64_t *hashes; bool *alive; int64_t *index; };

